/// <summary>
/// HSMobileOpsCountStageSvc's request. openStage: WarehouseId and, for a count against a counting journal, SourceJournalId.
/// submitLines: StageId, SubmissionId, LinesJson (an array of {ClientLineId, ItemId, ConfigId, SizeId, ColorId,
/// StyleId, BatchId, SerialId, LocationId, Quantity (inventory unit), UnitId, CountedAtUtc, SourceLineNum}) and
/// EndCount when the counter ends their count. getStageMode: WarehouseId.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountStageRequest
{
    str         dataAreaId;
    str         userName;
    str         deviceId;
    str         warehouseId;
    str         sourceJournalId;
    str         stageId;
    str         submissionId;
    str         linesJson;
    boolean     endCount;
}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public str parmDataAreaId(str _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('UserName')]
public str parmUserName(str _value = userName)
{
    userName = _value;
    return userName;
