{
    stageId = _value;
    return stageId;
}

[DataMemberAttribute('SubmissionId')]
public str parmSubmissionId(str _value = submissionId)
{
    submissionId = _value;
    return submissionId;
}

[DataMemberAttribute('LinesJson')]
public str parmLinesJson(str _value = linesJson)
{
    linesJson = _value;
    return linesJson;
}

[DataMemberAttribute('EndCount')]
public boolean parmEndCount(boolean _value = endCount)
{
    endCount = _value;
    return endCount;
}
